import logo from './logo.svg';
import './App.css';
import React, { useEffect } from 'react';
import { useState } from 'react';

function MyproccessBar({value}) {
  const [filled, setFilled] = useState(0);

  useEffect(() => {
    if (filled < value) {
      const timer = setTimeout(() => {
        setFilled((prev) => prev + 5);
      }, 50);

      return () => clearTimeout(timer);
    }
  }, [filled]);

  return (
    <div className="prossessbar">
      <div
        style={{
          height: "100%",
          width: `${filled}%`,
          backgroundColor: "purple",
          transition: "width 0.5s",
        }}
      ></div>

      <span className="my-proccess">
        {filled}%
      </span>
    </div>
  );
}

function Button(){
  const [message,setMessage] = useState("")
  const [message2, setMessage2] = useState("")
  function resultbutton(){
    setMessage("My e-mail: giannistamoulakatos@gmail.com");
    setMessage2("Linkdin: www.linkedin.com/in/γιάννης-σταμουλακάτος-a46364341");
  }
  return(
    <>
    <button className='ConButton' onClick={resultbutton}>
      Contact Me
    </button>
    <h2>{message}</h2>
    <h2>{message2}</h2>
    </>
  )
}

function NavigationBar(){
  return(
    <div className='NavigationBar'>
    <>
    <ul>
      <li><a href="#skills">My Skills</a></li>
      <li><a href="#projects">Selected Projects</a></li>
      <li><a href="#contact">Contact</a></li>
    </ul>
    </>
    </div>
  );
}

function Skills(){
  return(
    <div className='Skills'> 
    <>
    <h1>My Skills</h1>
    <div className='Back-End'>
    <h2>Back End</h2>
    <p>PHP</p>
    <MyproccessBar value={30}/>
    </div>
    <div className='Databases'>
    <h2>Databases</h2>
    <p>MySQL</p>
    <MyproccessBar value={60}/>
    </div>
    <div className='Front-End'>
    <h2>Front End</h2>
    <p>html</p>
    <MyproccessBar value={90}/>
    <p>css</p>
    <MyproccessBar value={90}/>
    <p>React</p>
    <MyproccessBar value={30}/> 
    </div>
    <div className='Tools'>
    <h2>Tools</h2>  
    <p>Git</p>
    <MyproccessBar value={80}/>  
    <p>Docker</p>
    <MyproccessBar value={70}/>
    <p>LaTeX</p>
    <MyproccessBar value={95}/>  
    <p>Wordpress</p>
    <MyproccessBar value={95}/>
    </div>
    <div className='OS'>
    <h2>Operating Systems</h2>
    <p>Debian</p>
    <MyproccessBar value={95}/> 
    <p>Kali</p>
    <MyproccessBar value={95}/>
    <p>Parrot</p>
    <MyproccessBar value={95}/>
    <p>freeBSD</p>
    <MyproccessBar value={50}/>
    <p>Windows/DOS</p>
    <MyproccessBar value={95}/>
    </div>
    <div className='Developing'>
    <h2>Developing</h2>
    <p>Python</p>
    <MyproccessBar value={90}/>
    <p>C</p>
    <MyproccessBar value={75}/>
    <p>C++</p>
    <MyproccessBar value={92}/>
    <p>Java</p>
    <MyproccessBar value={30}/>
    </div>
    </>
    </div>
  )
}

function Projects(){
  return(
    <div className='Projects'>
    <>
    <h1>Selected Projects</h1>
    <div className='Projectbox'>
    <a href='https://github.com/giannistamoulakatos/Avoiding_trafic_system_with_iot'>Avoiding Traffic System With IoT</a>
    <p>The project is my thesis. The goal is to avoid traffic accidents.</p>
    </div>
    <div className='Projectbox2'>
    <a href='https://github.com/giannistamoulakatos/Detection_dangerous_items_with_AI'>Detection Dangerous items with AI</a>
    <p>The project is one idea for one seminar. The goal is detection dangerous items for safety kids and other people </p>
    </div>
    </>
    </div>
  )
}


function App() {
  return(
    <div className='App'>
    <>
    <NavigationBar />
    <h1>Giannis Stamoulakatos</h1>
    <p>AI CyberSecyrity IoT and web developer</p>
    <div id='skills' className='skills'>
      <Skills />
    </div>
    <div id='projects' className='projects'>
      <Projects />
    </div>
    <div id='contact' className='contact'>
      <Button />
    </div>
    </>
    </div>
  )
}

export default App;
